import {
    type CommandExample,
    catchError,
    createHiddenDeprecatedTenantOption,
    extractErrorMessage,
    OutputFormatter,
    processContext,
    RESULTS,
} from "@uipath/common";
import { getFileSystem } from "@uipath/filesystem";
import type { EntityRecord } from "@uipath/uipath-typescript";
import { type Command, Option } from "commander";
import { readFileBinary, readJsonInput } from "../utils/input";
import { fail, requireDestructiveConfirmation } from "../utils/output";
import { connectOrFail } from "../utils/sdk-client";

interface ListOptions {
    tenant?: string;
    limit: string;
    offset?: string;
    cursor?: string;
    folderKey?: string;
}

interface GetOptions {
    tenant?: string;
    folderKey?: string;
}

interface InsertOptions {
    tenant?: string;
    file?: string;
    body?: string;
    folderKey?: string;
}

interface UpdateOptions {
    tenant?: string;
    file?: string;
    body?: string;
    folderKey?: string;
}

interface DeleteOptions {
    tenant?: string;
    yes?: boolean;
    confirm?: boolean;
    reason?: string;
    folderKey?: string;
}

interface QueryOptions {
    tenant?: string;
    file?: string;
    body?: string;
    limit: string;
    offset?: string;
    cursor?: string;
    folderKey?: string;
}

interface ImportOptions {
    tenant?: string;
    file?: string;
    folderKey?: string;
}

interface BatchResult {
    successRecords?: unknown[];
    failureRecords?: unknown[];
}

const RECORDS_LIST_EXAMPLES: CommandExample[] = [
    {
        Description: "List records in an entity.",
        Command:
            "uip df records list a1b2c3d4-0000-0000-0000-000000000001 --limit 2",
        Output: {
            Code: "RecordList",
            Data: {
                items: [
                    {
                        Id: "b2c3d4e5-0000-0000-0000-000000000001",
                        amount: 1500,
                    },
                    {
                        Id: "b2c3d4e5-0000-0000-0000-000000000002",
                        amount: 2750,
                    },
                ],
                totalCount: 2,
                hasNextPage: false,
            },
        },
    },
];

const RECORDS_GET_EXAMPLES: CommandExample[] = [
    {
        Description: "Get a record by ID",
        Command:
            "uip df records get a1b2c3d4-0000-0000-0000-000000000001 b2c3d4e5-0000-0000-0000-000000000001",
        Output: {
            Code: "RecordDetails",
            Data: {
                Id: "b2c3d4e5-0000-0000-0000-000000000001",
                amount: 1500,
                status: "Paid",
            },
        },
    },
];

